import { CLOUD_BLOB_COLORS, type CloudBlobColorId } from "./cloud-blobs.js";

export const CLOUD_BLOB_BODY_SIZE = 336;

export const CLOUD_BLOB_BODIES = {
  mist: "data:image/png;base64,",
  meadow: "data:image/png;base64,",
  lilac: "data:image/png;base64,",
  peach: "data:image/png;base64,",
  periwinkle: "data:image/png;base64,",
  slate: "data:image/png;base64,",
  apricot: "data:image/png;base64,",
  sage: "data:image/png;base64,",
  mauve: "data:image/png;base64,",
  sky: "data:image/png;base64,",
  tangerine: "data:image/png;base64,",
  sea: "data:image/png;base64,",
  violet: "data:image/png;base64,",
  cream: "data:image/png;base64,",
  steel: "data:image/png;base64,",
  fog: "data:image/png;base64,",
  iris: "data:image/png;base64,",
  chartreuse: "data:image/png;base64,",
  blush: "data:image/png;base64,",
} as const satisfies Record<CloudBlobColorId, string>;

export function cloudBlobBodyDataUrl(id: CloudBlobColorId): string {
  return CLOUD_BLOB_BODIES[id];
}

export const CLOUD_BLOB_BODY_IDS = CLOUD_BLOB_COLORS.map((color) => color.id);
